#include <cuda_runtime.h>
#include <vector>
#include <chrono>
#include <cstdio>
#include <cstdlib>
#include "../storeKVCache-cuda/kernels.h"
#define CK(x) do{auto e=(x);if(e!=cudaSuccess){fprintf(stderr,"%s\n",cudaGetErrorString(e));exit(1);}}while(0)
struct Case{int row;uint64_t *kc,*vc,*loc,*k,*v;std::vector<uint64_t> expected;};
int main(int argc,char**argv){int repeat=argc>1?atoi(argv[1]):100,batch=256,cache=512;std::vector<Case>cases;for(int row:{16,32,64,128}){Case c;c.row=row;std::vector<uint64_t>loc(batch),k(batch*row),v(batch*row);c.expected.resize(2*cache*row,0);for(int i=0;i<batch;i++)loc[i]=(i*73+19)%cache;for(int i=0;i<batch*row;i++){k[i]=uint64_t(i)*0x9e3779b97f4a7c15ULL+17;v[i]=~k[i];}for(int i=0;i<batch;i++)for(int j=0;j<row;j++){c.expected[loc[i]*row+j]=k[i*row+j];c.expected[cache*row+loc[i]*row+j]=v[i*row+j];}CK(cudaMalloc(&c.kc,cache*row*8));CK(cudaMalloc(&c.vc,cache*row*8));CK(cudaMalloc(&c.loc,batch*8));CK(cudaMalloc(&c.k,batch*row*8));CK(cudaMalloc(&c.v,batch*row*8));CK(cudaMemcpy(c.loc,loc.data(),batch*8,cudaMemcpyHostToDevice));CK(cudaMemcpy(c.k,k.data(),batch*row*8,cudaMemcpyHostToDevice));CK(cudaMemcpy(c.v,v.data(),batch*row*8,cudaMemcpyHostToDevice));cases.push_back(c);}
auto launch=[&](Case&c){uint64_t row=c.row;if(row%128==0)store_kv_cache_256x1_v4<<<32,256>>>(c.kc,c.vc,c.loc,uint64_t(batch),c.k,c.v,row,row,row/128);else if(row%64==0)store_kv_cache_256x1_v2<<<32,256>>>(c.kc,c.vc,c.loc,uint64_t(batch),c.k,c.v,row,row,row/64);else if(row%32==0)store_kv_cache_256x1<<<32,256>>>(c.kc,c.vc,c.loc,uint64_t(batch),c.k,c.v,row,row,row/32);else store_kv_cache_128x2<<<32,256>>>(c.kc,c.vc,c.loc,uint64_t(batch),c.k,c.v,row,row,row/16);};for(auto&c:cases)launch(c);CK(cudaDeviceSynchronize());bool all=true;
for(int trial=1;trial<=5;trial++){double times[4]={};std::vector<uint64_t>output;bool ok=true;int ci=0;for(auto&c:cases){int len=cache*c.row;CK(cudaMemset(c.kc,0,len*8));CK(cudaMemset(c.vc,0,len*8));CK(cudaDeviceSynchronize());auto t0=std::chrono::steady_clock::now();for(int k=0;k<repeat;k++)launch(c);CK(cudaDeviceSynchronize());times[ci++]=std::chrono::duration<double>(std::chrono::steady_clock::now()-t0).count()/repeat;std::vector<uint64_t>got(2*len);CK(cudaMemcpy(got.data(),c.kc,len*8,cudaMemcpyDeviceToHost));CK(cudaMemcpy(got.data()+len,c.vc,len*8,cudaMemcpyDeviceToHost));ok&=got==c.expected;output.insert(output.end(),got.begin(),got.end());}all&=ok;char file[100];sprintf(file,"storeKVCache_trial%d.bin",trial);FILE*f=fopen(file,"wb");fwrite(output.data(),8,output.size(),f);fclose(f);printf("STUDY_TRIAL {\"trial\":%d,\"time_seconds\":%.12g,\"correct\":%s,\"checked_values\":%d,\"max_abs_error\":0,\"max_rel_error\":0,\"timing_region\":\"sum_four_dispatch_width_kernel_regions_per_repeat\",\"jit_excluded\":true,\"internal_repeats\":%d,\"width_times_seconds\":[%.12g,%.12g,%.12g,%.12g],\"output_artifact\":{\"path\":\"%s\",\"dtype\":\"uint64\",\"count\":%d,\"byte_order\":\"little\"}}\n",trial,times[0]+times[1]+times[2]+times[3],ok?"true":"false",int(output.size()),repeat,times[0],times[1],times[2],times[3],file,int(output.size()));}for(auto&c:cases)for(auto p:{c.kc,c.vc,c.loc,c.k,c.v})CK(cudaFree(p));puts(all?"PASS":"FAIL");return all?0:1;}
